-- Reviewed additive system DB seed; run serially. No role grants or existing menu overwrites.
BEGIN;
SET @trade_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='trade' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @trade_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@trade_root AND path='order' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @trade_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@trade_root AND path='refund' AND menu_type='C' ORDER BY menu_id LIMIT 1);
COMMIT;
